public sealed record ContractVersion(decimal Fee, string Terms);      // immutable version
public sealed class Contract {                                        // continuity
    private readonly List<(DateTimeOffset From, ContractVersion V)> _history = new();
    public ContractVersion Current => _history[^1].V;
    public ContractVersion? AsOf(DateTimeOffset on) =>
        _history.FindLastIndex(h => h.From <= on) is var i && i >= 0 ? _history[i].V : null;
    public void Amend(DateTimeOffset effective, ContractVersion working) {  // working = Current with {..}
        var at = _history.FindIndex(h => h.From > effective);   // insertion point
        _history.Insert(at < 0 ? _history.Count : at, (effective, working));
    }
}

